-- Rivals Coach — compos d'équipe (contenu original, modifiable dans Admin > Compos).
-- À exécuter après 0010_guide_illustrations.sql. Ré-exécutable : les compos déjà présentes ne sont pas écrasées.

create table if not exists public.team_comps (
  id         serial primary key,
  slug       text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(slug) <= 60),
  status     text not null default 'draft' check (status in ('draft', 'published')),
  sort       int not null default 0,
  content    jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles (id) on delete set null default auth.uid()
);

drop trigger if exists team_comps_updated_at on public.team_comps;
create trigger team_comps_updated_at before update on public.team_comps
  for each row execute function public.set_updated_at();

alter table public.team_comps enable row level security;
drop policy if exists team_comps_select on public.team_comps;
drop policy if exists team_comps_admin_insert on public.team_comps;
drop policy if exists team_comps_admin_update on public.team_comps;
drop policy if exists team_comps_admin_delete on public.team_comps;
create policy team_comps_select on public.team_comps for select to authenticated
  using (status = 'published' or public.is_admin());
create policy team_comps_admin_insert on public.team_comps for insert to authenticated with check (public.is_admin());
create policy team_comps_admin_update on public.team_comps for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy team_comps_admin_delete on public.team_comps for delete to authenticated using (public.is_admin());

-- Six compos de départ
insert into public.team_comps (slug, status, sort, content) values ('brawl', 'published', 10, $c${"name": "Brawl au contact", "tagline": "On avance tous ensemble et on gagne le combat au corps à corps.", "style": "brawl", "difficulty": 1, "summary": "La compo la plus simple à jouer en groupe : deux tanks qui encaissent, deux duellistes qui tapent au contact, deux soigneurs qui soignent large. Personne ne part seul : la force de la compo, c'est d'être collés.", "heroes": [{"hero": "the-thing", "role": "Vanguard", "job": "Ouvre le combat, prend l'espace et reste au contact des ennemis."}, {"hero": "doctor-strange", "role": "Vanguard", "job": "Bouclier pour traverser la zone dangereuse, portail pour revenir vite sur le point."}, {"hero": "wolverine", "role": "Duelist", "job": "Tape les tanks adverses : plus le combat dure, plus il fait mal."}, {"hero": "the-punisher", "role": "Duelist", "job": "Dégâts constants à courte distance, tourelle pour tenir une entrée."}, {"hero": "luna-snow", "role": "Strategist", "job": "Soins de groupe constants, ult pour gagner le combat prolongé."}, {"hero": "mantis", "role": "Strategist", "job": "Bonus de dégâts sur les duellistes, soins sur la durée, sommeil sur un plongeur."}], "alternatives": [{"hero": "thor", "replaces": "the-thing", "note": "Plus de mobilité pour ramener un tank ennemi dans ta zone."}, {"hero": "emma-frost", "replaces": "doctor-strange", "note": "Bouclier solide et forme de diamant pour tenir le point."}, {"hero": "magik", "replaces": "wolverine", "note": "Plus de burst au contact, mais demande des combos."}, {"hero": "adam-warlock", "replaces": "mantis", "note": "Sa résurrection de groupe sauve un combat perdu."}], "best_when": ["Les cartes avec des **passages étroits** et des points fermés.", "Ton équipe aime jouer **groupée** et parle peu : il y a peu de timing à caler.", "L'équipe d'en face **plonge** sur vos soigneurs : groupés, vous les punissez."], "failure_signs": ["Vous **perdez de la vie avant même le contact** : l'ennemi vous harcèle de loin.", "Un tank part **seul devant** et meurt avant que les autres arrivent.", "Les soigneurs se retrouvent **loin derrière** et ne soignent plus personne."], "game_plan": ["Regroupez-vous **derrière un mur** juste avant la zone de combat.", "Le tank principal annonce le départ, puis **tout le monde avance en même temps**.", "Bouclier levé pour traverser la zone découverte, sans s'arrêter.", "Au contact, **tapez tous la même cible**, en commençant par le plus proche.", "Gardez l'**ult de soin** pour le moment où les ennemis lancent leurs ults."], "strong_vs": [{"comp": "dive", "note": "Groupés, vous attrapez les plongeurs qui arrivent dans votre zone."}], "weak_vs": [{"comp": "poke", "note": "Ils vous usent de loin avant le contact : coupez la distance par un mur ou un flanc."}], "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style."}$c$::jsonb) on conflict (slug) do nothing;
insert into public.team_comps (slug, status, sort, content) values ('dive', 'published', 20, $c${"name": "Plongée coordonnée", "tagline": "Tout le monde saute sur la même cible au même moment, puis ressort.", "style": "dive", "difficulty": 3, "summary": "Une compo très mobile qui gagne en éliminant un soigneur ou un tireur avant que le combat commence vraiment. Elle demande de la communication : une plongée à deux réussit, une plongée seule meurt.", "heroes": [{"hero": "venom", "role": "Vanguard", "job": "Plonge le premier sur la backline et encaisse grâce à sa vie bonus."}, {"hero": "captain-america", "role": "Vanguard", "job": "Suit Venom, protège les plongeurs et relance la pression."}, {"hero": "black-panther", "role": "Duelist", "job": "Élimine la cible marquée par la plongée, puis ressort avec ses dashes."}, {"hero": "psylocke", "role": "Duelist", "job": "Arrive par derrière, achève les cibles basses, repart invisible."}, {"hero": "rocket-raccoon", "role": "Strategist", "job": "Suit l'équipe avec son jetpack, balise de résurrection pour les plongées ratées."}, {"hero": "ultron", "role": "Strategist", "job": "Vole avec les plongeurs et les soigne là où les autres soigneurs ne vont pas."}], "alternatives": [{"hero": "thor", "replaces": "captain-america", "note": "Plus de dégâts, et son dash ramène une cible."}, {"hero": "spider-man", "replaces": "black-panther", "note": "Très mobile, idéal pour harceler les soigneurs."}, {"hero": "magik", "replaces": "psylocke", "note": "Portails pour entrer et sortir, gros burst."}, {"hero": "jeff-the-land-shark", "replaces": "rocket-raccoon", "note": "Se faufile partout et soigne en mouvement."}], "best_when": ["Les cartes **ouvertes avec de la hauteur** et plusieurs chemins.", "L'équipe d'en face a des **tireurs fixes** (snipers, harceleurs à distance).", "Vous jouez **en vocal** : le moment de la plongée doit être annoncé."], "failure_signs": ["Les plongeurs **arrivent un par un** et meurent un par un.", "La cible plongée **survit à chaque fois** : elle a trop de soins ou de protection.", "Les ennemis jouent **collés en brawl** : vous plongez au milieu de six joueurs."], "game_plan": ["Choisissez **une seule cible** avant le combat, idéalement un soigneur isolé.", "Annoncez le compte « 3, 2, 1 » et **plongez tous en même temps**.", "Tuez la cible, puis **ressortez tout de suite** vers votre équipe.", "Rechargez vos capacités à l'abri, et recommencez sur la cible suivante."], "strong_vs": [{"comp": "poke", "note": "Les tireurs à distance sont isolés : plongez dessus."}], "weak_vs": [{"comp": "brawl", "note": "Une équipe collée vous attend et vous écrase."}, {"comp": "anti-dive", "note": "Elle est construite exprès pour vous punir."}], "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style."}$c$::jsonb) on conflict (slug) do nothing;
insert into public.team_comps (slug, status, sort, content) values ('poke', 'published', 30, $c${"name": "Harcèlement à distance", "tagline": "On use l'adversaire de loin, derrière les boucliers, avant tout contact.", "style": "poke", "difficulty": 2, "summary": "Une compo qui gagne les combats avant qu'ils commencent : les tireurs touchent de loin, les tanks protègent avec leurs boucliers, et l'ennemi arrive au contact déjà affaibli. Il faut viser juste et tenir sa position.", "heroes": [{"hero": "doctor-strange", "role": "Vanguard", "job": "Bouclier frontal pour protéger les tireurs, portail pour reprendre la position."}, {"hero": "magneto", "role": "Vanguard", "job": "Boucliers et bulles pour que les tireurs survivent aux échanges."}, {"hero": "hela", "role": "Duelist", "job": "Tirs à la tête de loin, élimine tout ce qui sort à découvert."}, {"hero": "hawkeye", "role": "Duelist", "job": "Flèches à très longue portée sur les cibles qui reculent."}, {"hero": "invisible-woman", "role": "Strategist", "job": "Bouclier sur les alliés et poussée pour éloigner ceux qui s'approchent."}, {"hero": "adam-warlock", "role": "Strategist", "job": "Soins à distance et résurrection pour retourner un combat."}], "alternatives": [{"hero": "emma-frost", "replaces": "doctor-strange", "note": "Bouclier solide, et elle tient mieux si l'ennemi arrive au contact."}, {"hero": "iron-man", "replaces": "hawkeye", "note": "Harcèlement depuis les airs, difficile à atteindre."}, {"hero": "elsa-bloodstone", "replaces": "hela", "note": "Dégâts à distance avec de quoi fuir une plongée."}, {"hero": "ultron", "replaces": "adam-warlock", "note": "Soins à distance en restant en hauteur."}], "best_when": ["Les cartes avec de **longues lignes de vue** et des positions en hauteur.", "Vos tireurs **visent bien** : la compo dépend de leurs dégâts.", "L'équipe d'en face **avance lentement** et doit traverser une zone découverte."], "failure_signs": ["Des plongeurs **atteignent vos tireurs** à chaque combat.", "Vos boucliers **tombent avant** que l'ennemi ait perdu de la vie.", "L'ennemi **contourne par les flancs** au lieu de traverser votre ligne de tir."], "game_plan": ["Prenez une **position avec une longue ligne de vue**, boucliers devant.", "Tirez **avant le combat** : chaque dégât compte quand ils traversent la zone.", "Concentrez le feu sur le **tank** pour casser leur avancée, puis les fragiles.", "Si quelqu'un plonge, **reculez ensemble** et tapez-le tous."], "strong_vs": [{"comp": "brawl", "note": "Ils doivent traverser votre zone de tir pour vous atteindre."}], "weak_vs": [{"comp": "dive", "note": "Les plongeurs arrivent sur vos tireurs sans passer par vos boucliers."}], "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style."}$c$::jsonb) on conflict (slug) do nothing;
insert into public.team_comps (slug, status, sort, content) values ('anti-dive', 'published', 40, $c${"name": "Contre-plongée", "tagline": "On protège les soigneurs et on punit chaque plongeur.", "style": "peel", "difficulty": 2, "summary": "La réponse quand l'équipe d'en face plonge sans arrêt sur vos soigneurs. Murs, toiles, tourelles et poussées : chaque plongeur qui arrive est ralenti, isolé puis éliminé à plusieurs.", "heroes": [{"hero": "groot", "role": "Vanguard", "job": "Murs pour couper les chemins d'entrée et isoler les plongeurs."}, {"hero": "peni-parker", "role": "Vanguard", "job": "Toiles et mines autour des soigneurs, nid d'araignées pour tenir la zone."}, {"hero": "namor", "role": "Duelist", "job": "Tourelles près des soigneurs : elles tapent tout ce qui plonge."}, {"hero": "the-punisher", "role": "Duelist", "job": "Dégâts constants pour finir les plongeurs coincés."}, {"hero": "luna-snow", "role": "Strategist", "job": "Soins de groupe, et une boule de neige qui arrête un plongeur."}, {"hero": "invisible-woman", "role": "Strategist", "job": "Poussée pour renvoyer un plongeur, bouclier sur l'allié ciblé."}], "alternatives": [{"hero": "emma-frost", "replaces": "groot", "note": "Son étranglement arrête un plongeur net."}, {"hero": "squirrel-girl", "replaces": "the-punisher", "note": "Le gland étourdissant immobilise les plongeurs, même en ult."}, {"hero": "mantis", "replaces": "invisible-woman", "note": "Le sommeil endort un plongeur au bon moment."}, {"hero": "rocket-raccoon", "replaces": "luna-snow", "note": "Sa balise de résurrection rattrape une plongée réussie."}], "best_when": ["L'équipe d'en face joue **plusieurs plongeurs** (Venom, Spider-Man, Black Panther, Psylocke…).", "Vos soigneurs **meurent en premier** à chaque combat.", "Les points avec **peu d'entrées** : les murs et les mines les bloquent facilement."], "failure_signs": ["L'ennemi **ne plonge plus** et vous harcèle de loin : passez sur une autre compo.", "Vos tourelles et mines sont **posées trop loin** des soigneurs.", "Tout le monde **court après un plongeur** et abandonne le point."], "game_plan": ["Posez tourelles, mines et toiles **autour des soigneurs**, pas devant.", "Dès qu'un plongeur arrive, **tout le monde se retourne** sur lui.", "Coupez sa sortie avec un mur ou un étourdissement, puis **finissez-le à plusieurs**.", "Une fois le plongeur mort, **reprenez l'espace** devant : c'est du 6 contre 5."], "strong_vs": [{"comp": "dive", "note": "Chaque plongeur est attendu et puni."}], "weak_vs": [{"comp": "poke", "note": "Vos outils de protection ne servent à rien contre des tirs de loin."}], "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style."}$c$::jsonb) on conflict (slug) do nothing;
insert into public.team_comps (slug, status, sort, content) values ('groot-trap', 'published', 50, $c${"name": "Piège de Groot", "tagline": "L'ult de Groot regroupe les ennemis, les autres ults finissent le travail.", "style": "pull", "difficulty": 2, "summary": "Une compo construite autour d'un combo d'ults : Groot attire et retient les ennemis au même endroit, puis Moon Knight et Winter Soldier les éliminent en groupe. Le reste du temps, elle joue comme un brawl solide.", "heroes": [{"hero": "groot", "role": "Vanguard", "job": "Lance l'ult qui regroupe les ennemis, et coupe le terrain avec ses murs."}, {"hero": "emma-frost", "role": "Vanguard", "job": "Tank principal : tient le front pendant que Groot prépare son ult."}, {"hero": "moon-knight", "role": "Duelist", "job": "Ult sur le groupe retenu par Groot : énormes dégâts de zone."}, {"hero": "winter-soldier", "role": "Duelist", "job": "Ult en combo avec Groot, et solide au front le reste du temps."}, {"hero": "cloak-and-dagger", "role": "Strategist", "job": "Voile pour que ton équipe frappe à travers le combo."}, {"hero": "luna-snow", "role": "Strategist", "job": "Soins de groupe, et ult pour survivre au combo adverse."}], "alternatives": [{"hero": "namor", "replaces": "moon-knight", "note": "Ses tourelles et son ult se combinent bien avec Groot."}, {"hero": "human-torch", "replaces": "winter-soldier", "note": "Zones de feu sur les ennemis regroupés."}, {"hero": "angela", "replaces": "emma-frost", "note": "Ses ennemis attachés ne peuvent plus fuir l'ult."}], "best_when": ["Les **points fermés** où les ennemis restent groupés.", "Vous avez **les ults chargées en même temps** : comptez-les avant le combat.", "L'équipe d'en face joue **un seul soigneur avec une ult de soin** : forcez-la d'abord."], "failure_signs": ["Un **Adam Warlock** ressuscite tout le monde après votre combo.", "Le **bouclier de Magneto** bloque le projectile de Groot.", "Vous lancez les ults **les unes après les autres** au lieu d'ensemble."], "game_plan": ["Avant le combat, **annoncez qui a son ult** : Groot, Moon Knight, Winter Soldier.", "Jouez un brawl classique jusqu'à ce que les ennemis **se regroupent**.", "Groot lance son ult **sur le groupe**, puis les ults de dégâts suivent immédiatement.", "Si l'ennemi lance une ult de soin, **attendez sa fin** pour relancer le combo."], "strong_vs": [{"comp": "brawl", "note": "Une équipe groupée est le rêve de Groot."}], "weak_vs": [{"comp": "dive", "note": "Des plongeurs éparpillés évitent le piège."}], "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style."}$c$::jsonb) on conflict (slug) do nothing;
insert into public.team_comps (slug, status, sort, content) values ('air', 'published', 60, $c${"name": "Pression aérienne", "tagline": "Les duellistes attaquent du ciel, l'équipe adverse doit lever la tête.", "style": "angle", "difficulty": 2, "summary": "Une compo qui met deux duellistes volants en hauteur : ils touchent tout le monde depuis des angles que l'ennemi ne couvre pas. Elle punit les équipes sans tireurs capables de viser en l'air.", "heroes": [{"hero": "doctor-strange", "role": "Vanguard", "job": "Occupe le front au sol et protège la zone avec son bouclier."}, {"hero": "thor", "role": "Vanguard", "job": "Pression au sol : force l'ennemi à regarder devant pendant que les volants frappent."}, {"hero": "iron-man", "role": "Duelist", "job": "Harcèle depuis les airs avec de gros dégâts de zone."}, {"hero": "human-torch", "role": "Duelist", "job": "Pose des zones de feu depuis le ciel pour couper l'équipe adverse."}, {"hero": "ultron", "role": "Strategist", "job": "Vole avec les duellistes et les soigne en hauteur."}, {"hero": "adam-warlock", "role": "Strategist", "job": "Soins à distance et lien d'âmes pour encaisser les tirs."}], "alternatives": [{"hero": "storm", "replaces": "human-torch", "note": "Volante aussi, avec des auras pour l'équipe."}, {"hero": "phoenix", "replaces": "iron-man", "note": "Mobile en hauteur, gros dégâts de zone."}, {"hero": "magneto", "replaces": "thor", "note": "Plus solide, et ses bulles protègent les volants."}], "best_when": ["L'équipe d'en face n'a **pas de tireurs précis** (peu de Hela, Hawkeye, Punisher…).", "Les cartes avec **un ciel dégagé** et peu de plafonds.", "Vos volants savent **changer d'angle** plutôt que rester immobiles."], "failure_signs": ["Vos volants **tombent dès qu'ils décollent** : l'ennemi a des tireurs précis.", "Les tanks au sol **meurent seuls** parce que les volants sont trop loin.", "Vos soigneurs **ne voient plus** les volants et ne les soignent pas."], "game_plan": ["Les tanks occupent l'avant **au sol** pour attirer l'attention.", "Les volants montent **sur deux angles différents** : l'ennemi ne peut pas regarder les deux.", "Visez d'abord les **tireurs capables de vous toucher** en l'air.", "Redescendez derrière un mur quand vous êtes bas en vie : **pas de soin en plein ciel**."], "strong_vs": [{"comp": "brawl", "note": "Une équipe de mêlée ne peut pas vous atteindre en l'air."}], "weak_vs": [{"comp": "poke", "note": "Des tireurs à distance vous visent sans difficulté."}], "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style."}$c$::jsonb) on conflict (slug) do nothing;
